cards.extra:
echo '== imports'; I=$(go list -e -overlay $P/overlay.json -f '{{join .Imports " "}}' ./daemon) || exit 1; for i in $I; do case $i in context|encoding/json|errors|fmt|net/http|os|path/filepath|sort|strconv|strings|sync|time|unicode/utf8|morphstudio/stream|morphstudio/session|morphstudio/eventlog|morphstudio/telegram|morphstudio/runner|morphstudio/queue|morphstudio/claude|morphstudio/github|morphstudio/bootstrap|morphstudio/registry|morphstudio/gitrules|morphstudio/control|morphstudio/supervisor) ;; *) echo "imports: package daemon imports $i (allowed: context, encoding/json, errors, fmt, net/http, os, path/filepath, sort, strconv, strings, sync, time, unicode/utf8, morphstudio/stream, morphstudio/session, morphstudio/eventlog, morphstudio/telegram, morphstudio/runner, morphstudio/queue, morphstudio/claude, morphstudio/github, morphstudio/bootstrap, morphstudio/registry, morphstudio/gitrules, morphstudio/control, morphstudio/supervisor)"; exit 1;; esac; done
echo '== clock'; C=$(gofmt -l -r 'time.Now -> time.Time' daemon/daemon.go 2>&1)$(gofmt -l -r 'time.Since -> time.Time' daemon/daemon.go 2>&1)$(gofmt -l -r 'time.Until -> time.Time' daemon/daemon.go 2>&1); [ -z "$C" ] || { echo "clock: daemon/daemon.go reads time.Now, time.Since or time.Until (package daemon reads no clock: every time is a call of Deps.Now)"; exit 1; }
echo '== net'; for x in http.DefaultClient http.Get http.Post http.PostForm http.Head http.ListenAndServe http.ListenAndServeTLS; do C=$(gofmt -l -r "$x -> http.NoBody" daemon/daemon.go 2>&1); [ -z "$C" ] || { echo "net: daemon/daemon.go uses $x (no HTTP client of its own and never a listener in package daemon: GitHub through Deps.GitHubDo)"; exit 1; }; done

